113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
119	        validateRequiredFields(ownerFieldsDto);
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
123	        owner.setEmail(normalizeEmail(owner.getEmail()));
124	        if (owner.getRegistrationDate() == null) {
125	            owner.setRegistrationDate(LocalDate.now());
126	        }
127	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
128	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
129	        }
130	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
131	            && isDuplicateHousehold(owner.getLastName(), owner.getAddress())) {
132	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
133	        }
134	        owner.setCustomerCode(buildCustomerCode(owner.getLastName()));
135	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
136	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
137	        this.clinicService.saveOwner(owner);
138	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
